mapper.select:
SELECT bar.billExceptionHandleRecordId, bar.adjustDate, bar.orderDate, bar.billNum, bar.patientId, bar.regDentistId, bar.adjustOperatorId FROM ( SELECT behr.id AS billExceptionHandleRecordId, behdr.orgId, DATE_FORMAT( behr.crt_time, '%Y-%m-%d' ) adjustDate, behdr.orderDate AS orderDate, behdr.billNumber AS billNum, behdr.patientId patientId, tr.dentist_id AS regDentistId, behr.crt_id AS adjustOperatorId FROM ( SELECT id, treatment_record_id, crt_id, crt_time FROM bill_exception_handle_record WHERE operate_type = 2 ) behr LEFT JOIN ( SELECT behdr.bill_handle_record_id AS billExceptionhandleRecordId, br.patient_id AS patientId, br.org_id as orgId, br.bill_number AS billNumber, DATE_FORMAT( br.crt_time, '%Y-%m-%d' ) AS billDate, DATE_FORMAT( ord.crt_time, '%Y-%m-%d' ) AS orderDate FROM bill_exception_handle_detail_record behdr LEFT JOIN bill_record br ON behdr.associate_record_id = br.order_record_id LEFT JOIN order_record ord ON behdr.associate_record_id = ord.id ) behdr ON behr.id = behdr.billExceptionhandleRecordId LEFT JOIN treatment_record tr ON behr.treatment_record_id = tr.id ) bar
and bar.orgId = #{query.orgId}
and bar.billNum like concat('%', #{query.billNum}, '%')
and bar.adjustDate >= #{query.adjustStartDate}
and bar.adjustDate <= #{query.adjustEndDate}
and bar.billDate >= #{query.billStartDate}
and bar.billDate <= #{query.billEndDate}
and bar.regDentistId in
#{item}
ORDER BY bar.adjustDate DESC

SELECT bar.billExceptionHandleRecordId, bar.revokeDate, bar.orderDate, bar.actualAmount, bar.receivedAmount, bar.chargeDate, bar.billNum, bar.patientId, bar.regDentistId, bar.revokeOperatorId FROM ( SELECT behr.id AS billExceptionHandleRecordId, bpr.orgId, DATE_FORMAT( behr.crt_time, '%Y-%m-%d' ) revokeDate, bpr.orderDate AS orderDate, bpr.actualAmount, bpr.receivedAmount, bpr.chargeDate, bpr.billNum, bpr.patientId patientId, tr.dentist_id AS regDentistId, behr.crt_id AS revokeOperatorId FROM ( SELECT id, treatment_record_id, handled_record_id, crt_id, crt_time FROM bill_exception_handle_record WHERE operate_type = 1 ) behr LEFT JOIN ( SELECT bpr.id, bpr.org_id AS orgId, bpr.patient_id AS patientId, bpr.received_amount AS receivedAmount, br.actual_receivable_amount AS actualAmount, br.bill_number AS billNum, DATE_FORMAT( bpr.crt_time, '%Y-%m-%d' ) AS chargeDate, DATE_FORMAT( ord.crt_time, '%Y-%m-%d' ) AS orderDate FROM bill_pay_record bpr LEFT JOIN bill_record br ON bpr.bill_record_id = br.id LEFT JOIN order_record ord ON bpr.order_record_id = ord.id ) bpr ON behr.handled_record_id = bpr.id LEFT JOIN treatment_record tr ON behr.treatment_record_id = tr.id ) bar
and bar.orgId = #{query.orgId}
and bar.billNum like concat('%', #{query.billNum}, '%')
and bar.revokeDate >= #{query.revokeStartDate}
and bar.revokeDate <= #{query.revokeEndDate}
and bar.chargeDate >= #{query.chargeStartDate}
and bar.chargeDate <= #{query.chargeEndDate}
and bar.regDentistId in
#{item}
ORDER BY bar.revokeDate DESC

SELECT bar.billExceptionHandleRecordId, bar.adjustDate, bar.orderDate, bar.actualAmount, bar.receivedAmount, bar.chargeDate, bar.billNum, bar.patientId, bar.regDentistId, bar.adjustOperatorId FROM ( SELECT behr.id AS billExceptionHandleRecordId, bpr.orgId, DATE_FORMAT( behr.crt_time, '%Y-%m-%d' ) adjustDate, bpr.orderDate AS orderDate, bpr.actualAmount, bpr.receivedAmount, bpr.chargeDate, bpr.billNum, bpr.patientId patientId, tr.dentist_id AS regDentistId, behr.crt_id AS adjustOperatorId FROM ( SELECT id, treatment_record_id, handled_record_id, crt_id, crt_time FROM bill_exception_handle_record WHERE operate_type = 0 ) behr LEFT JOIN ( SELECT bpr.id, bpr.org_id AS orgId, bpr.patient_id AS patientId, bpr.received_amount AS receivedAmount, br.actual_receivable_amount AS actualAmount, br.bill_number AS billNum, DATE_FORMAT( bpr.crt_time, '%Y-%m-%d' ) AS chargeDate, DATE_FORMAT( ord.crt_time, '%Y-%m-%d' ) AS orderDate FROM bill_pay_record bpr LEFT JOIN bill_record br ON bpr.bill_record_id = br.id LEFT JOIN order_record ord ON bpr.order_record_id = ord.id ) bpr ON behr.handled_record_id = bpr.id LEFT JOIN treatment_record tr ON behr.treatment_record_id = tr.id ) bar
and bar.orgId = #{query.orgId}
and bar.billNum like concat('%', #{query.billNum}, '%')
and bar.adjustDate >= #{query.adjustStartDate}
and bar.adjustDate <= #{query.adjustEndDate}
and bar.chargeDate >= #{query.chargeStartDate}
and bar.chargeDate <= #{query.chargeEndDate}
and bar.regDentistId in
#{item}
ORDER BY bar.adjustDate DESC
